composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      HASURA_GRAPHQL_DATABASE_URL: "postgres://hasura:{{env.POSTGRES_PASSWORD}}@{{serviceName}}-postgres:5432/hasura"
      HASURA_GRAPHQL_ADMIN_SECRET: {{env.HASURA_GRAPHQL_ADMIN_SECRET}}
      HASURA_GRAPHQL_ENABLE_CONSOLE: {{env.HASURA_GRAPHQL_ENABLE_CONSOLE}}
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: postgres:16-alpine
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: hasura
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      POSTGRES_DB: hasura
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
